<main class="main"><header class="topbar"><div><h4 class="mb-0"><?=e($titles[$page]??'Storage QR')?></h4><small class="text-secondary"><?=logged_in()?'Kelola storage dengan mudah':'Mode Guest - hanya melihat data'?></small></div><?php if(logged_in()):?><div class="dropdown"><button class="btn btn-light border dropdown-toggle" data-bs-toggle="dropdown">👤 <?=e($_SESSION['user']['nama'])?></button><ul class="dropdown-menu dropdown-menu-end"><li><span class="dropdown-item-text text-secondary small"><?=e(role_label())?></span></li><li><a class="dropdown-item" href="<?=url('logout.php')?>">Keluar</a></li></ul></div><?php else:?><a class="btn btn-primary" href="<?=url('login.php')?>">Masuk / Daftar</a><?php endif;?></header><div class="container-fluid py-4"><?php show_flash();?><script>document.addEventListener('DOMContentLoaded',()=>{const heading=[...document.querySelectorAll('h5')].find(x=>x.textContent.trim()==='Aktivitas storage');if(!heading)return;const cardBody=heading.closest('.card-body');const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));const refresh=()=>fetch('activity_feed.php',{cache:'no-store'}).then(response=>response.json()).then(data=>{while(heading.nextElementSibling)heading.nextElementSibling.remove();data.activities.forEach(item=>{const color=item.jenis==='masuk'?'success':'warning';cardBody.insertAdjacentHTML('beforeend','<div class="storage-activity-item border-bottom py-2"><b>'+esc(item.nama)+'</b> <span class="badge text-bg-'+color+'">'+esc(item.jenis)+'</span><br><small class="text-secondary">'+item.jumlah+' unit oleh '+esc(item.user)+' · '+esc(item.waktu)+'</small></div>');});}).catch(()=>{});refresh();setInterval(refresh,5000);});</script>
